 ru:[
 'Откройте каждую историю|Все жанры|Жанры|Воспроизвести|Назад|Только что добавлено|Независимые оригиналы|ИСТОРИИ МИРА, ВСЕГО В НЕСКОЛЬКИХ МИНУТАХ.|В ЦЕНТРЕ ВНИМАНИЯ|Двое незнакомцев. Пропущенный поезд. Ночь, меняющая всё.|Ваша история, их новое увлечение.|Творите на своём языке. Найдите своих зрителей.|Начать создавать|Истории без границ|21 язык интерфейса, мир разных взглядов.|Ещё для вас|Начать смотреть бесплатно|Попробуйте другой язык, жанр или запрос.|Ваша следующая история ждёт.|Немного драмы, множество открытий.|Сохраняйте любимое, открывайте эпизоды и поддерживайте авторов.|Впервые здесь?|Уже есть аккаунт?|Я принимаю Условия использования и Политику конфиденциальности.|Сделайте эту историю своей.|Пополнить кошелёк',
 'Сумма|Платите только за нужные эпизоды.|Активность появится после первой операции.|Закрытый эпизод|Откройте один раз и пересматривайте когда захотите.|Пополните баланс для продолжения|70% получает автор|30% поддерживают платформу|Эпизод открыт. Приятного просмотра!|Тестовый платёж|Подтвердить тестовый платёж|Платежи пока недоступны.|Платёж завершён. Аккаунт обновлён.|Платёж отменён. Баланс не изменился.|Стать издателем|5 GB хранилища включено|До 3 минут и 75 MB на эпизод|Вам достаётся 70% продаж эпизодов|Ваша серия. Ваша цена.|Покупки эпизодов|Общий доход|В архиве|Ваша первая история начинается здесь.|Создайте сериал, добавьте обложку и загрузите папку эпизодов.|Данные сериала|Выберите язык, на котором говорят в эпизодах.',
 'JPEG, PNG или WebP · до 5 MB · рекомендуется вертикальный формат|Цены эпизодов|Первые выбранные эпизоды бесплатны, остальные по вашей цене.|Вернуть в черновик|Перетащите видео или выберите папку. Сортировка по имени файла.|Остановить загрузку|Сохраните данные сериала перед загрузкой.|Длительность|Размер|Удалить этот эпизод? Действие нельзя отменить.|Ваш сериал опубликован!|Изменения сохранены.|Запрошенный общий объём（GB）|Начальные 5 GB. Дополнительный объём рассматривается и оценивается отдельно.|Запрос отправлен.|Вывод от эквивалента HK$20, после проверки.|Оценка в HKD|Курс ориентировочный. Итоговую конвертацию и комиссии определяет провайдер.|Запросы на выплату|Запросов на выплату пока нет.|Настройки|В меню браузера выберите «Добавить на главный экран».|Участники|Запросы хранилища|Запросы выплат|Нет ожидающих запросов.',
 'Продажи эпизодов|Доля платформы|Доход от активации（HKD）|Независимые истории. Настоящие связи.|Все права защищены.|Ссылка скопирована.|Здесь место вашей следующей любимой истории.|Выберите историю. Мы запомним место.|Начните бесплатно, без входа.|Завершено|Уведомления|Вы всё посмотрели.|Добро пожаловать|Создайте короткую незабываемую историю.|Минимум US$0.10. Вам достаётся 70% каждой покупки.|Эпизоды ещё не загружены.|Сохранить и продолжить|Подтверждаем платёж…|Показать пароль|Скрыть пароль|Заполните все обязательные поля.|Примите условия для продолжения.|Видео должно читаться и длиться не более 3 минут.|Этот эпизод превышает 75 MB.|Очередь загрузки завершена.|Войдите для продолжения',
 ],
