 'Jumlah|Bayar hanya episod yang ingin anda tonton.|Aktiviti muncul selepas transaksi pertama.|Episod terkunci|Buka sekali, tonton semula bila-bila masa.|Tambah dana untuk teruskan|70% kepada pencipta|30% menyokong platform|Episod dibuka. Selamat menonton!|Bayaran ujian|Sahkan bayaran ujian|Bayaran belum tersedia.|Bayaran selesai. Akaun dikemas kini.|Bayaran dibatalkan. Baki tidak berubah.|Menjadi penerbit|Storan 5 GB termasuk|Maksimum 3 minit dan 75 MB setiap episod|Anda menerima 70% jualan episod|Siri anda. Harga anda.|Pembukaan episod|Jumlah pendapatan|Diarkibkan|Cerita pertama anda bermula di sini.|Cipta siri, tambah kulit dan muat naik folder episod.|Butiran siri|Pilih bahasa yang dituturkan dalam episod.',
 'JPEG, PNG atau WebP · sehingga 5 MB · potret disyorkan|Harga episod|Episod awal percuma, selebihnya mengikut harga yang ditetapkan.|Kembali ke draf|Letak video atau pilih folder. Disusun mengikut nama fail.|Hentikan muat naik|Simpan butiran siri sebelum memuat naik.|Tempoh|Saiz|Padam episod ini? Tindakan ini tidak boleh dibatalkan.|Siri anda sudah disiarkan!|Perubahan disimpan.|Jumlah storan diminta（GB）|Mula dengan 5 GB. Storan tambahan disemak dan diberi sebut harga berasingan.|Permintaan dihantar.|Pengeluaran dari nilai setara HK$20, selepas semakan.|Anggaran nilai HKD|Kadar indikatif. Penyedia bayaran menentukan penukaran akhir dan fi.|Permintaan pengeluaran|Belum ada permintaan pengeluaran.|Pilihan|Pilih “Tambah ke Skrin Utama” dalam menu pelayar.|Ahli|Permintaan storan|Permintaan pengeluaran|Tiada permintaan tertunda.',
 'Jualan episod|Bahagian platform|Hasil pengaktifan（HKD）|Cerita bebas. Hubungan sebenar.|Hak cipta terpelihara.|Pautan disalin.|Tempat cerita kegemaran seterusnya di sini.|Pilih cerita. Kami ingat kedudukan anda.|Mula percuma. Tanpa log masuk.|Selesai|Pemberitahuan|Semua pemberitahuan sudah dibaca.|Selamat datang|Cipta sesuatu yang ringkas dan tidak dilupakan.|Minimum US$0.10. Anda menerima 70% setiap pembukaan.|Belum ada episod dimuat naik.|Simpan dan teruskan|Mengesahkan bayaran…|Tunjuk kata laluan|Sembunyi kata laluan|Lengkapkan semua medan wajib.|Terima terma untuk teruskan.|Video mesti boleh dibaca dan tidak melebihi 3 minit.|Episod ini melebihi had 75 MB.|Giliran muat naik selesai.|Log masuk untuk teruskan',
