 'JPEG、PNG 或 WebP · 最大 5 MB · 建議直式圖片|單集定價|前幾集免費，其後按單集售價收費。|改為草稿|拖放影片或選擇資料夾，按檔名排序。|停止上傳|先儲存劇集資料，再上傳影片。|時長|大小|確定移除此集？此操作無法還原。|你的劇集已上線！|已儲存變更。|申請總空間（GB）|先享 5 GB；額外空間須審核並另行報價。|申請已送出。|最低提款為等值 HK$20，經審核後付款。|預計港幣金額|匯率僅供參考，最終兌換及費用由付款服務商決定。|提款申請|尚未有提款申請。|偏好設定|在瀏覽器選單選擇「加入主畫面」。|會員|空間申請|提款申請|目前沒有待審核申請。',
