 'JPEG、PNG 或 WebP · 最大 5 MB · 建议竖版图片|单集定价|前几集免费，其后按单集售价收费。|改为草稿|拖放视频或选择文件夹，按文件名排序。|停止上传|先保存剧集信息，再上传视频。|时长|大小|确定移除此集？此操作无法撤销。|你的剧集已上线！|已保存更改。|申请总空间（GB）|先享 5 GB；额外空间须审核并另行报价。|申请已发送。|最低提现为等值 HK$20，审核后付款。|预计港币金额|汇率仅供参考，最终兑换及费用由支付服务商决定。|提现申请|暂无提现申请。|偏好设置|在浏览器菜单选择“添加到主屏幕”。|会员|空间申请|提现申请|目前没有待审核申请。',
 '单集销售额|平台收入|开通收入（港币）|独立创作，真实连接。|保留所有权利。|已复制链接。|下一部最爱就在这里。|选一个故事，我们会记住你的进度。|免费开始，无须登录。|已完成|通知|你已查看所有通知。|欢迎|创作一段令人难忘的小故事。|最低 US$0.10，每次解锁你可获得 70%。|尚未上传视频。|保存并继续|正在确认付款…|显示密码|隐藏密码|请填写所有必填字段。|请先同意条款。|视频须可读取，且不超过 3 分钟。|本集超过 75 MB 上限。|上传队列已完成。|登录后继续',
