 hi:[
 'हर कहानी खोजें|सभी शैलियाँ|शैलियाँ|चलाएँ|पिछला|अभी जोड़ा गया|स्वतंत्र मौलिक कहानियाँ|दुनिया की कहानियाँ, बस कुछ मिनट दूर।|खास पेशकश|दो अजनबी, छूटी ट्रेन और सब बदल देने वाली रात।|आपकी कहानी, उनकी अगली पसंद।|अपनी भाषा में बनाएँ, अपने दर्शक खोजें।|बनाना शुरू करें|सरहदों से परे कहानियाँ|21 इंटरफ़ेस भाषाएँ, दुनिया भर के नज़रिए।|और पसंदीदा कहानियाँ|मुफ़्त देखना शुरू करें|दूसरी भाषा, शैली या खोज आज़माएँ।|आपकी अगली कहानी इंतज़ार में है।|थोड़ा ड्रामा, ढेर सारी खोज।|पसंदीदा सहेजें, एपिसोड खोलें और क्रिएटर्स का साथ दें।|यहाँ नए हैं?|पहले से खाता है?|मैं उपयोग की शर्तें और गोपनीयता नीति स्वीकार करता हूँ।|इस कहानी को अपना बनाएँ।|वॉलेट में पैसे जोड़ें',
 'राशि|केवल अपनी पसंद के एपिसोड के लिए भुगतान करें।|पहले लेन-देन के बाद गतिविधि दिखाई देगी।|लॉक किया गया एपिसोड|एक बार खोलें, जब चाहें फिर देखें।|जारी रखने के लिए पैसे जोड़ें|70% क्रिएटर को मिलता है|30% प्लेटफ़ॉर्म के लिए|एपिसोड खुल गया। कहानी का आनंद लें!|परीक्षण भुगतान|परीक्षण भुगतान की पुष्टि|भुगतान अभी उपलब्ध नहीं है।|भुगतान पूरा। खाता अपडेट हो गया।|भुगतान रद्द। शेष नहीं बदला।|प्रकाशक बनें|5 GB स्टोरेज शामिल|हर एपिसोड 3 मिनट और 75 MB तक|एपिसोड बिक्री का 70% आपका|आपकी सीरीज़, आपका मूल्य।|एपिसोड अनलॉक|कुल कमाई|संग्रहीत|आपकी पहली कहानी यहाँ शुरू होती है।|सीरीज़ बनाएँ, कवर जोड़ें और एपिसोड फ़ोल्डर अपलोड करें।|सीरीज़ की जानकारी|एपिसोड में बोली जाने वाली भाषा चुनें।',
 'JPEG, PNG या WebP · 5 MB तक · लंबवत चित्र बेहतर|एपिसोड मूल्य|शुरुआती चुने गए एपिसोड मुफ़्त, बाकी तय कीमत पर।|ड्राफ़्ट में लौटें|वीडियो छोड़ें या फ़ोल्डर चुनें। फ़ाइल नाम से क्रम बनता है।|अपलोड रोकें|अपलोड से पहले सीरीज़ की जानकारी सहेजें।|अवधि|आकार|यह एपिसोड हटाएँ? इसे वापस नहीं लाया जा सकेगा।|आपकी सीरीज़ लाइव है!|बदलाव सहेजे गए।|माँगा गया कुल स्टोरेज（GB）|शुरुआत में 5 GB। अतिरिक्त स्थान की समीक्षा और अलग मूल्य तय होगा।|अनुरोध भेज दिया गया।|निकासी HK$20 के बराबर से शुरू। भुगतान से पहले समीक्षा होगी।|अनुमानित HKD राशि|यह सांकेतिक दर है। अंतिम दर और शुल्क भुगतान प्रदाता तय करता है।|निकासी अनुरोध|अभी कोई निकासी अनुरोध नहीं।|प्राथमिकताएँ|ब्राउज़र मेनू में “होम स्क्रीन पर जोड़ें” चुनें।|सदस्य|स्टोरेज अनुरोध|निकासी अनुरोध|कोई लंबित अनुरोध नहीं।',
 'एपिसोड बिक्री|प्लेटफ़ॉर्म का हिस्सा|सक्रियण आय（HKD）|स्वतंत्र कहानियाँ, असली रिश्ते।|सर्वाधिकार सुरक्षित।|लिंक कॉपी हुआ।|अगली पसंदीदा कहानी यहाँ रखें।|कहानी चुनें, हम आपकी जगह याद रखेंगे।|मुफ़्त शुरुआत, लॉग इन ज़रूरी नहीं।|पूरा हुआ|सूचनाएँ|सभी सूचनाएँ देख ली गईं।|स्वागत है|कुछ छोटा और यादगार बनाएँ।|न्यूनतम US$0.10। हर अनलॉक का 70% आपका।|अभी कोई एपिसोड अपलोड नहीं।|सहेजें और जारी रखें|भुगतान की पुष्टि हो रही है…|पासवर्ड दिखाएँ|पासवर्ड छिपाएँ|सभी आवश्यक फ़ील्ड भरें।|जारी रखने के लिए शर्तें स्वीकार करें।|वीडियो पढ़ने योग्य और 3 मिनट से कम होना चाहिए।|एपिसोड 75 MB सीमा से बड़ा है।|अपलोड कतार पूरी हुई।|जारी रखने के लिए लॉग इन करें',
 ],
