 'JPEG, PNG ou WebP · até 5 MB · retrato recomendado|Preço dos episódios|Os primeiros episódios são grátis; os demais usam o preço definido.|Voltar ao rascunho|Arraste vídeos ou escolha uma pasta. Ordem por nome do arquivo.|Parar envio|Salve os detalhes da série para começar a enviar.|Duração|Tamanho|Remover este episódio? Esta ação não pode ser desfeita.|Sua série está no ar!|Alterações salvas.|Armazenamento total solicitado（GB）|Comece com 5 GB. Espaço adicional passa por análise e orçamento separado.|Solicitação enviada.|Saque a partir do equivalente a HK$20, sujeito a análise.|Valor estimado em HKD|Taxa indicativa. O provedor define conversão final e tarifas.|Solicitações de saque|Nenhuma solicitação de saque.|Preferências|No menu do navegador, escolha “Adicionar à tela inicial”.|Membros|Solicitações de armazenamento|Solicitações de saque|Nenhuma solicitação pendente.',
