 'Montant|Payez uniquement les épisodes qui vous intéressent.|L’activité apparaîtra après votre première transaction.|Épisode verrouillé|Débloquez une fois et regardez quand vous voulez.|Ajoutez des fonds pour continuer|70% reviennent au créateur|30% soutiennent la plateforme|Épisode débloqué. Bonne découverte !|Paiement de test|Confirmer le paiement de test|Les paiements ne sont pas encore disponibles.|Paiement terminé. Compte mis à jour.|Paiement annulé. Solde inchangé.|Devenir éditeur|5 GB de stockage inclus|3 minutes et 75 MB maximum par épisode|Vous recevez 70% des ventes|Votre série. Votre prix.|Déblocages d’épisodes|Revenus cumulés|Archivé|Votre première histoire commence ici.|Créez une série, ajoutez une couverture et importez un dossier d’épisodes.|Détails de la série|Choisissez la langue parlée dans les épisodes.',
 'JPEG, PNG ou WebP · 5 MB maximum · portrait recommandé|Tarifs des épisodes|Les premiers épisodes sont gratuits, les suivants au prix choisi.|Revenir au brouillon|Déposez des vidéos ou choisissez un dossier. Tri par nom de fichier.|Arrêter l’importation|Enregistrez les détails avant d’importer.|Durée|Taille|Supprimer cet épisode ? Cette action est irréversible.|Votre série est en ligne !|Modifications enregistrées.|Stockage total demandé（GB）|5 GB au départ. Tout supplément est examiné et fait l’objet d’un devis.|Demande envoyée.|Retraits dès l’équivalent de HK$20, après examen.|Valeur estimée en HKD|Taux indicatif. Le prestataire fixe la conversion et les frais finaux.|Demandes de retrait|Aucune demande de retrait.|Préférences|Dans le navigateur, choisissez « Ajouter à l’écran d’accueil ».|Membres|Demandes de stockage|Demandes de retrait|Aucune demande en attente.',
 'Ventes d’épisodes|Part de la plateforme|Recettes d’activation（HKD）|Histoires indépendantes. Vraies connexions.|Tous droits réservés.|Lien copié.|Votre prochain favori a sa place ici.|Choisissez une histoire. Nous garderons votre place.|Commencez gratuitement, sans connexion.|Terminé|Notifications|Vous êtes à jour.|Bienvenue|Créez un petit récit inoubliable.|Minimum US$0.10. Vous recevez 70% de chaque déblocage.|Aucun épisode importé.|Enregistrer et continuer|Confirmation du paiement…|Afficher le mot de passe|Masquer le mot de passe|Remplissez tous les champs obligatoires.|Acceptez les conditions pour continuer.|La vidéo doit être lisible et durer 3 minutes maximum.|Cet épisode dépasse 75 MB.|File d’importation terminée.|Connectez-vous pour continuer',
