export const additionalMessages:Record<string,Record<string,string>>={};
for(const [locale,groups] of Object.entries(rows)){
  groups.forEach((group,i)=>{if(group.split('|').length!==26)throw new Error(`Additional translations ${locale}, group ${i}: ${group.split('|').length}/26`);});
  const values=groups.join('|').split('|');additionalMessages[locale]=Object.fromEntries(extraKeys.map((key,i)=>[key,values[i]]));
}

